mapper.update:
UPDATE homework_submission
SET homework_id=#{homeworkId}, student_id=#{studentId}, content=#{content},
    attachment_url=#{attachmentUrl}, attachment_name=#{attachmentName},
    submit_time=#{submitTime}, score=#{score}, teacher_comment=#{teacherComment}, status=#{status}
WHERE submission_id=#{submissionId}

UPDATE homework_submission
SET ai_score=#{aiScore}, ai_report=#{aiReport}, ai_status=#{aiStatus}, ai_scored_at=#{aiScoredAt}
WHERE submission_id=#{submissionId}
